h3. Context
* {{src/jira.ts:9}} {{searchAssigned}} {{searchAssigned}} puts {{email}} into the JQL string without escaping. A value containing {{"}} rewrites the query. Escape backslash and {{"}} before interpolating.
{panel}

h3. Details
Paths and line numbers refer to commit {{7a9f10e84d875d9fa1433eb401e8efe6f077f5e4}} on main.

{code:javascript}
// src/jira.ts:7-13

export async function searchAssigned(email: string): Promise<unknown> {
  const jql = `assignee = "${email}" ORDER BY created DESC`;
  const res = await fetch(`${JIRA}/search?jql=${encodeURIComponent(jql)}`);
  return res.json();
}

{code}
